import{_ as a,o as r,c as o,a2 as i}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Постоянная совместная колония","description":"","frontmatter":{"pageId":"players/coop","contentRevision":2},"headers":[],"relativePath":"ru/players/coop.md","filePath":"ru/players/coop.md"}'),l={name:"ru/players/coop.md"};function t(c,e,s,p,n,h){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="постоянная-совместная-колония" tabindex="-1">Постоянная совместная колония <a class="header-anchor" href="#постоянная-совместная-колония" aria-label="Permalink to &quot;Постоянная совместная колония&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><ol><li>Хозяин открывает <strong>Совместная колония</strong> под чатом и приглашает партнёра.</li><li>Партнёр открывает то же окно, обновляет список и принимает.</li><li>Хозяин назначает свободных колонистов домашней карты.</li><li>Партнёр из своей домашней колонии нажимает <strong>Войти в колонию</strong>. Его дом сохраняется до загрузки зеркала.</li><li>Партнёр управляет назначенными пешками, включая работу, расписание, экипировку и бой; хозяин продолжает игру и пишет единственный канонический сейв.</li></ol><p>Членство переживает перезапуск. Изменение назначений или отзыв завершает текущую сессию. Для завершения партнёр выходит домой.</p><h2 id="coop-check" tabindex="-1">Кто что контролирует после приглашения? <a class="header-anchor" href="#coop-check" aria-label="Permalink to &quot;Кто что контролирует после приглашения? {#coop-check}&quot;">​</a></h2><p>Приглашение, принятие, назначение пешек и вход — четыре отдельных шага. Само членство не даёт управление всем поселением. Перед входом хозяин должен назначить свободных колонистов выбранной домашней карты, а партнёр — находиться в своей домашней колонии.</p><p>Для первой проверки назначь одну пешку, оставь вторую без назначения. Партнёр меняет работу/расписание назначенной; хозяин видит исполнение. Неназначенная не должна получать приказы партнёра. Затем партнёр выходит и входит снова: членство сохраняется, пешки остаются у хозяина, в почте партнёра не появляется «возврат» хозяйских колонистов.</p><p>Назначение — реальное доверие к экипировке и боевым приказам пешки. Не выдавай его незнакомому игроку лишь для просмотра карты. Для экскурсии подходит обычный/live-визит.</p><h2 id="coop-recovery" tabindex="-1">Отзыв, занятость и восстановление назначений <a class="header-anchor" href="#coop-recovery" aria-label="Permalink to &quot;Отзыв, занятость и восстановление назначений {#coop-recovery}&quot;">​</a></h2><p>Одновременно входит один партнёр; до восьми приглашений/участников и 32 назначенных пешек — пределы режима, не число одновременных клиентов. Отказ «занято» не лечится вторым аккаунтом.</p><p>Изменение назначений или отзыв завершает текущий coop. После rollback членство остаётся, но хозяин выбирает пешек заново: числовой id в старом сейве мог означать другой объект. Reset удаляет разрешения колонии; archive/restore той же колонии сохраняет членство, но завершает активный live.</p><p>Если хозяин ушёл, автономного продолжения нет. Сохранившийся локальный mirror не становится вторым каноническим сейвом. Администратор может просмотреть членство и отозвать доступ, но не должен чинить ситуацию выдачей копий пешек.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Один партнёр одновременно, до 8 приглашений/участников и 32 пешек. Хозяин должен быть онлайн дома. Кошелёк, отправка вещей и админ-права не передаются. Reset удаляет членство; archive/restore сохраняет; rollback сохраняет членство, но очищает назначения. Пешки хозяина не возвращаются партнёру почтой.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./live">Live: живая карта</a></li><li><a href="./../admins/administration">Панель и модерация</a></li><li><a href="./saves-recovery">Сохранения и восстановление</a></li></ul>',17)])])}const m=a(l,[["render",t]]);export{u as __pageData,m as default};
